package server.life;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;

/**
 * Ticket 81 (owner 2026-10-28, draft): max HP overrides for mobs whose WZ HP is far off the classic curve (the
 * post-Big-Bang mobs: Arcane River, Grandis, Future/Twilight Perion). The table is a jar resource,
 * {@code soloMapling/mob-hp-overrides.tsv}, generated by tools/economy/gen_bb_drops.py (rules in
 * docs/economy/bb-drops/RULES.md). LifeFactory applies it after its own hard-coded HP, so a row wins over both the
 * WZ value and those. Only max HP changes: EXP, level and everything else stay as the WZ says. The client needs
 * nothing: a normal mob's HP bar is the percentage the server sends and a boss bar is the server's HP.
 *
 * <p>Off with {@code -Dslums.mobHpOverrides=false} (read once, at the first mob load).
 */
public final class MobHpOverrides {

    private static final Logger log = LoggerFactory.getLogger(MobHpOverrides.class);
    static final String RESOURCE = "/soloMapling/mob-hp-overrides.tsv";
    private static final Map<Integer, Long> HP = load();

    private MobHpOverrides() {
    }

    /** The overriding max HP for {@code mobId}, or {@code fallback} when it has none (or overrides are off). */
    public static long maxHp(int mobId, long fallback) {
        Long hp = HP.get(mobId);
        return hp != null ? hp : fallback;
    }

    static Map<Integer, Long> table() {
        return HP;
    }

    private static Map<Integer, Long> load() {
        if (!Boolean.parseBoolean(System.getProperty("slums.mobHpOverrides", "true"))) {
            log.info("mob HP overrides are off (-Dslums.mobHpOverrides=false)");
            return Collections.emptyMap();
        }
        try (InputStream in = MobHpOverrides.class.getResourceAsStream(RESOURCE)) {
            if (in == null) {
                log.warn("{} is missing from the jar; no mob HP overrides", RESOURCE);
                return Collections.emptyMap();
            }
            return parse(new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8)));
        } catch (IOException | RuntimeException e) {
            log.error("cannot read {}; no mob HP overrides", RESOURCE, e);
            return Collections.emptyMap();
        }
    }

    static Map<Integer, Long> parse(BufferedReader r) throws IOException {
        Map<Integer, Long> out = new HashMap<>();
        String line;
        while ((line = r.readLine()) != null) {
            if (line.isBlank() || line.startsWith("#")) {
                continue;
            }
            String[] f = line.split("\t", -1);
            long hp = Long.parseLong(f[1].trim());
            if (hp <= 0) {
                throw new IllegalArgumentException("max HP must be positive: " + line);
            }
            if (out.put(Integer.parseInt(f[0].trim()), hp) != null) {
                throw new IllegalArgumentException("mob listed twice: " + line);
            }
        }
        return Collections.unmodifiableMap(out);
    }
}
